toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  unitPriceCents: number,
  quantity: number,
  weightGrams?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines and subtotal", () => {
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 2)], 2000),
    ).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1)], 1000),
      ).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal >= freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(
        calc.computeShippingCents([makeLine("a", 5000, 1)], 5000),
      ).toBe(0);
    });

    it("returns flat fee when subtotal < freeOverCents", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(
        calc.computeShippingCents([makeLine("a", 4999, 1)], 4999),
      ).toBe(599);
    });

    it("returns 0 when subtotal exceeds freeOverCents", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 6000),
      ).toBe(0);
    });

    it("freeOverCents of 0 means always free when cart has items", () => {
      const calc = new FlatShippingCalculator(599, 0);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 100),
      ).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      // Product with no weight
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1)], 1000),
      ).toBe(0);
    });

    it("selects first bracket when weight <= smallest upToGrams", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1, 400)], 1000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1, 500)], 1000),
      ).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1, 501)], 1000),
      ).toBe(700);
    });

    it("selects highest bracket for weight at its boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1, 5000)], 1000),
      ).toBe(1200);
    });

    it("uses last bracket cost as overflow default", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1, 6000)], 1000),
      ).toBe(1200);
    });

    it("uses explicit overflowCostCents when weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      expect(
        calcWithOverflow.computeShippingCents(
          [makeLine("a", 1000, 1, 3000)],
          1000,
        ),
      ).toBe(1500);
    });

    it("accumulates weight across multiple lines", () => {
      // 2 lines: 300g * 2 = 600g, 400g * 1 = 400g → total 1000g
      const lines: CartLine[] = [
        makeLine("a", 100, 2, 300),
        makeLine("b", 200, 1, 400),
      ];
      // 1000g fits in 500 < 1000 <= 2000 bracket → 700
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first bracket (500) → 300
      expect(
        unordered.computeShippingCents([makeLine("a", 100, 1, 400)], 100),
      ).toBe(300);
    });
  });
});

