import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(widget, 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("w1");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("tracks different products separately", () => {
    cart.add(widget, 1);
    cart.add(gadget, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects non-positive quantity", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unit price", () => {
    const bad: Product = { id: "b", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true and removes existing product", () => {
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(widget, 2);
    cart.updateQuantity("w1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nope", 1)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy — mutation does not affect the cart", () => {
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Internal state unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 * 1000
    cart.add(gadget, 1); // 1 * 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount via injected DiscountPolicy", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(widget, 3); // subtotal 3000
    const totals = cart.totals();
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(3000);
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(2500); // 3000 - 500
  });

  it("clamps discount to [0, subtotal]", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(widget, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(widget, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on the discounted subtotal", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
    cart.add(widget, 1); // subtotal 1000, discount 200, discounted 800
    const totals = cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(totals.taxCents).toBe(80);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator });
    cart.add(widget, 1); // subtotal 1000, discount 200
    const totals = cart.totals();
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800, // discounted subtotal
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
    cart.add(widget, 1); // subtotal 1000
    const totals = cart.totals();
    // discountedSubtotal = 1000 - 100 = 900
    // total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default region US when not specified", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — async checkout", () => {
  it("returns totals and lines for basic checkout", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("w1");
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
  });

  it("checks inventory for each line", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
    expect(inventoryChecker.check).toHaveBeenCalledWith("g1", 1);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w1");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w1");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart();
    cart.add(widget, 1); // subtotal 1000
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    expect(taxProvider.getRate).toHaveBeenCalledWith("US");
    expect(result.totals.taxCents).toBe(100); // 10% of 1000
  });

  it("applies discount + async tax + shipping composition", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
    cart.add(widget, 2); // subtotal 2000
    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // discounted = 2000 - 200 = 1800; tax = 10% of 1800 = 180; shipping = 500
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1800 + 180 + 500);
    expect(taxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(widget, 1);
    await expect(
      cart.checkout({ asyncTaxProvider: taxProvider }),
    ).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price fetch failed")),
    };
    const cart = new Cart();
    cart.add(widget, 1);
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price fetch failed",
    );
  });

  it("runs price refresh before inventory check", async () => {
    const callOrder: string[] = [];
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("price");
        return 1000;
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("inventory");
        return { available: true };
      }),
    };
    const cart = new Cart();
    cart.add(widget, 1);
    await cart.checkout({ priceFetcher, inventoryChecker });
    expect(callOrder).toEqual(["price", "inventory"]);
  });

  it("generates default message for inventory denial without reason", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
      expect(invErr.message).toContain("w1");
    }
  });

  it("checkout with no collaborators uses sync totals", async () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalled();
    expect(result.totals.taxCents).toBe(100);
  });
});

